#!/bin/sh
command -v python3>/dev/null||exit 127;python3 -c 'import math,struct,wave;R=12000;w=input("keyword:").encode();g=1;exec("for c in w:g=g*257+c+1");s=input("sec:").strip();T=max(.5,float(s))if s else 10+g%31;r=48+g%25;M=g//25%2<1;b=72+4*(g//50%31);S=[0,2,4,5,7,9,11]if M else[0,2,3,5,7,8,10];D=[-3,-2,-1,0,1,2,3];U=lambda c:(c%7,c//7%4,c//28%4,c//112%3,c//336);Q=lambda n:n>1 and(n==2 or n%2 and all(n%d for d in range(3,math.isqrt(n)+1,2)));X=lambda n:next(x for x in range(n+1,2*n)if Q(x));N=max(1,math.ceil(T*b/30));q=0;p=2;G=1;K=[];E=[];Z=[];he=hp=0;exec("for i in range(N):\n L=128*(1+(g//(i+1)+i)%4);V=[c for c in range(L)if(q+D[U(c)[0]])%7 in{(i//4)%7,(i//4+2)%7,(i//4+4)%7}];he+=math.log2(len(V));td=(g//(i+1)+i)%7;ti=(g//(i+3)+i)%4;tv=(g//(i+5)+i)%4;tr=(g//(i+7)+i)%3;F=lambda c:min(((q+D[U(c)[0]])%7-td)%7,(td-(q+D[U(c)[0]])%7)%7)+(U(c)[1]!=ti)+(U(c)[2]!=tv)+(U(c)[3]!=tr)+U(c)[4];m=min(map(F,V));A=[c for c in V if F(c)==m];hp+=math.log2(len(A));Z+=([i]if len(A)==1 else[]);c=min(A);k,I,v,h,z=U(c);q=(q+D[k])%7;K.append(c);E.append((r+S[q],I,v,h,z));G*=p**(c+1);p=X(p)");x=G;p=2;J=[];exec("for c in K:\n e=0\n while x%p==0:e+=1;x//=p\n J.append(e-1);p=X(p)");ok=J==K and x==1;L=int(R*30/b);O=[];exec("for n,I,v,h,z in E:\n f=440*2**((n-69)/12);a=[.5,.75,1][h]\n for j in range(L):\n  t=j/R;ph=2*math.pi*f*t;e=min(1,j/80,max(0,(a*L-j)/180));m=sum(math.sin((k+1)*ph)/(k+1)for k in range(1+I+z));vv=0 if not v else .25*math.sin(ph)*(1+.3*math.sin(2*math.pi*(250+120*v)*t));O.append(int(4800*e*(m+vv+.18*math.sin(ph/2))))");O=O[:int(R*T)];o=f"music_{g%1000000}.wav";v=wave.open(o,"w");v.setparams((1,2,R,0,"NONE",""));v.writeframes(b"".join(struct.pack("<h",max(-32767,min(32767,a)))for a in O));v.close();print(f"WAV={o} ZERO={Z} H_evo={he/N:.2f} H_phi0={hp/N:.2f} H={0 if ok else 1} Z={bool(ok)} G_bits={G.bit_length()}")'